def fill_codes(apps, schema_editor):
    """Give every existing school a School ID such as NewHope-003."""
    import re

    School = apps.get_model("core", "School")
    used = set()
    for number, school in enumerate(School.objects.order_by("id"), start=1):
        if school.code:
            used.add(school.code.lower())
            continue
        words = re.findall(r"[A-Za-z0-9]+", school.name or "School")
        stem = "".join(w[:1].upper() + w[1:].lower() for w in words[:2]) or "School"
        n = number
        while f"{stem[:20]}-{n:03d}".lower() in used:
            n += 1
        school.code = f"{stem[:20]}-{n:03d}"
        used.add(school.code.lower())
        school.save(update_fields=["code"])


